//! Ollama-compatible HTTP API on port 11435.
//!
//! Security posture (V5 – hardened):
//!   - API server is **opt-in** (`api_server_enabled` defaults to `false`).
//!   - Bound to 127.0.0.1 only — never exposed to the LAN. A local inference
//!     server that also deletes model files has no business listening on
//!     0.0.0.0, where any device on the network could drive it.
//!   - Every route requires `Authorization: Bearer <token>`. The token is a
//!     per-launch random secret generated by the Tauri shell and shared with
//!     the legitimate consumers (the sidecar via the injected model api key,
//!     and external apps via `~/.feral/api-token`). This closes the
//!     same-host attack surface: other local processes and browser-based
//!     DNS-rebinding/CORS probes can reach the port but cannot use it.
//!   - `/api/delete` validates the model name as a bare filename and confirms
//!     containment inside the models directory before touching the disk, so a
//!     crafted `name` like `../../../../etc/passwd` can no longer escape it.
use axum::{
    extract::{Query, State},
    http::{header, HeaderMap, HeaderName, HeaderValue, Request, StatusCode},
    middleware::{self, Next},
    response::sse::{Event, Sse},
    response::{IntoResponse, Response},
    routing::{delete, get, post},
    Json, Router,
};
use futures::stream::Stream;
use serde::Deserialize;
use serde_json::{json, Value};
use std::convert::Infallible;
use std::sync::atomic::AtomicBool;
use std::sync::Arc;
use tokio::sync::broadcast;
use tower_http::cors::{AllowOrigin, CorsLayer};

use crate::byok;
use crate::connectors as connector_catalog;
use crate::inference::{InferParams, Message, ModelManager};
use crate::models;
use crate::runtime::RuntimeState;

#[derive(Clone)]
pub struct ApiState {
    pub manager: Arc<ModelManager>,
        /// Per-launch random bearer token. Every request must present it as
    /// `Authorization: Bearer <token>`. Shared with the sidecar and external
    /// consumers out of band — see the module docstring.
    pub token: Arc<str>,
    /// Faza 4.5 Slice 3: the whole runtime, so the Public Runtime API
    /// `/runtime/*` endpoints report live status/inventory and `/events`
    /// subscribes to the observability bus. `manager`/`token` above stay as
    /// convenience handles the pre-Slice-3 handlers already read.
    pub runtime: Arc<RuntimeState>,
}

pub fn router(state: ApiState) -> Router {
    // CORS stays restricted to loopback origins. With bearer auth on top, a
    // malicious page that guesses the origin still cannot forge the token.
    let cors = CorsLayer::new()
        .allow_origin(AllowOrigin::predicate(|origin: &HeaderValue, _| {
            is_loopback_origin(origin.as_bytes())
        }))
        .allow_methods(tower_http::cors::Any)
        .allow_headers(tower_http::cors::Any);

    Router::new()
        // Ollama-compatible
        .route("/api/tags", get(api_tags))
        .route("/api/show", post(api_show))
        .route("/api/generate", post(api_generate))
        .route("/api/chat", post(api_chat))
        .route("/api/delete", delete(api_delete))
        // OpenAI-compatible aliases
        .route("/v1/models", get(v1_models))
        .route("/v1/chat/completions", post(v1_chat_completions))
        // llama.cpp-server-compatible tokenizer (P3). The agent sidecar calls
        // this for accurate context accounting with the loaded model's real
        // vocabulary; its GPT-2 BPE fallback miscounts everything else.
        .route("/tokenize", post(api_tokenize))
        // Public Runtime API v1 (Faza 4.5 Slice 3, spec D3). Same posture as
        // the rest of this router: 127.0.0.1-only + bearer token. This first
        // vertical serves the Rust-local read-only surface + the `/events`
        // observability stream; the sidecar-round-trip endpoints
        // (/runtime/chat, /tools, /connectors, /memory, /dreams) land next.
        .route("/runtime/chat", post(runtime_chat))
        .route("/runtime/ask/respond", post(runtime_ask_respond))
        .route(
            "/runtime/connectors",
            get(runtime_connectors_list).post(runtime_connectors_save),
        )
        .route("/runtime/connectors/reload", post(runtime_connectors_reload))
        // The one tool a voice call can reach. It lives here rather than on a
        // pipe to the agent process because the LiveKit SDK forks a supervised
        // child per call, and that child does not have the worker's stdin —
        // taking it over is what made the runner time out and the call fail
        // with nobody in the room. A loopback route with the bearer token the
        // API already requires works from any process, including a forked one.
        .route("/runtime/voice/tool", post(runtime_voice_tool))
        .route("/runtime/voice/speak", post(runtime_voice_speak))
        .route("/runtime/voice/transcribe", post(runtime_voice_transcribe))
        .route("/runtime/shutdown", post(runtime_shutdown))
        .route("/runtime/status", get(runtime_status))
        .route("/runtime/models", get(runtime_models))
        .route("/runtime/model", post(runtime_set_model))
        .route("/runtime/lora", get(runtime_lora))
        .route("/runtime/lora/train", post(runtime_lora_train))
        .route("/runtime/lora/reviews", get(runtime_lora_reviews))
        .route("/runtime/lora/reviews/resolve", post(runtime_lora_review_resolve))
        .route("/runtime/manifest", get(runtime_manifest))
        .route("/runtime/sessions", get(runtime_sessions))
        // Sprint 1.6 — Memory Resume. Headless / TUI clients hit this; the
        // desktop Tauri app uses the `get_last_task` command which delegates
        // to the same sidecar roundtrip but stays in-process. Same shape:
        // subscribe-before-send, wait for `resume_get_result`.
        .route("/runtime/resume", get(runtime_resume))
        // /compact (OpenClaw slash parity) — summarize the older portion of
        // one session's transcript now. Body: `{ session_id? }` (default
        // "default"). Sidecar round-trip correlated by id, reply type
        // `compact_result`. The summarizer is a full LLM completion, so the
        // wait is generous (120s) — on CPU it can take as long as a turn.
        .route("/runtime/session/compact", post(runtime_session_compact))
        // Sprint 2 / audit C-1 — hardware probe for the TUI Setup Wizard.
        // Same shape as the Tauri command `get_system_info`. The wizard used
        // to hard-code "rtx 4070 · 12 GB" on every machine; now it reads
        // the real GPU/VRAM/RAM/disk via sysinfo_mod::detect().
        .route("/system_info", get(system_info))
        // Sprint 2 / audit C-2 — real provider key validation for the wizard.
        // Body: `{ provider_id, api_key, base_url? }`. Returns the provider's
        // real status text — "401 Unauthorized", "Invalid API key", etc. —
        // so the wizard can surface the actual reason instead of a fake ✓.
        .route("/providers/test", post(providers_test))
        // Phase 0b (2026-07-07, terminal-onboarding slice) — persist a
        // provider's API key to the OS keychain and its metadata to
        // `~/.feral/byok.json`. Body: `{ provider_id, enabled, api_key,
        // base_url?, default_model? }`. Empty `api_key` leaves the keychain
        // entry untouched (matches the existing `byok::save` semantics). The
        // response never echoes the key. Closes the silent key-drop bug
        // where the headless wizard validated a freshly-entered key against
        // `/providers/test` but never persisted it to the keychain, so the
        // next launch reported "No API key configured".
        .route("/runtime/byok/save", post(runtime_byok_save))
        // Sprint 2 / audit C-5 — real model download with progress.
        // POST kicks off a background download and returns a download id;
        // GET on the same id returns the latest progress + status.
        // The TUI Setup Wizard polls the GET route every 500ms.
        .route("/runtime/models/install", post(runtime_models_install))
        .route("/runtime/models/download/:id", get(runtime_models_download))
        // Faza 6 (L6) Meta Evolution — sidecar round-trips correlated by id.
        // `/meta/evaluate` is an alias of `/meta/current`: the fitness is
        // computed live from the journal window on every status read.
        .route("/meta/current", get(meta_current))
        .route("/meta/evaluate", post(meta_current_post))
        .route("/meta/history", get(meta_history))
        .route("/meta/evolve", post(meta_evolve))
        .route("/meta/rollback", post(meta_rollback))
        // Slice A5 (L5 Governance API — spec §12). Same posture as /meta/*:
        // 127.0.0.1 + bearer token, sidecar roundtrip per op, single
        // governance_result reply paired by `id`. Routes are tagged with
        // their operation class (read/evolve/govern) as code comments; v1
        // honors all three under the same token. The helper below mirrors
        // `meta_roundtrip` line-by-line but filters on governance_result.
        .route("/governance/policy",   get(governance_policy))             // read
        .route("/governance/proposals", get(governance_proposals))          // read
        .route("/governance/history",  get(governance_history_route))       // read
        .route("/governance/verify",   get(governance_verify_route))        // read
        .route("/governance/propose",   post(governance_propose_route))      // evolve
        .route("/governance/approve",   post(governance_approve_route))      // govern
        .route("/governance/reject",    post(governance_reject_route))       // govern
        .route("/governance/rollback",  post(governance_rollback_route))     // govern
        .route("/governance/freeze",    post(governance_freeze_route))       // govern
        .route("/governance/unfreeze",  post(governance_unfreeze_route))     // govern
        // Phase B (L4 Architecture Evolution — spec §10). Same posture as
        // /governance/*: sidecar roundtrip per op, one modules_result reply
        // paired by `id`. `/modules/evaluate` runs the paired eval suite on
        // the live model — its roundtrip uses a long deadline.
        .route("/modules",              get(modules_list_route))              // read
        .route("/modules/evaluate",     post(module_evaluate_route))          // evolve
        .route("/modules/propose",      post(module_propose_route))           // evolve
        .route("/modules/:id",          get(module_show_route))               // read
        .route("/modules/:id/approve",  post(module_approve_route))           // govern
        .route("/modules/:id/reject",   post(module_reject_route))            // govern
        .route("/modules/:id/demote",   post(module_demote_route))            // govern
        .route("/events", get(runtime_events))
        // Phase 1 (2026-07-07) — canonical provider + connector catalogs.
        // Both surfaces (Go TUI wizard, desktop React OnboardingWizard)
        // hit these at boot instead of carrying their own copy. The
        // response carries an `X-Cinderpaw-Catalog-Version` header —
        // clients treat a mismatch as "fall back to the bundled slice
        // with a clearly surfaced warning", never as a silent drop.
        // Guided setup (2026-07-10 OpenClaw onboarding-parity spec). One
        // ladder, every surface: `feral setup`, the Go TUI, the desktop
        // wizard all consume the same detect → verify → persist seam.
        // Verify runs a REAL completion (not a ping); `persist: true` is
        // honored only on success, so config can never end up pointing at
        // an unverified route through this surface.
        .route("/runtime/setup/detect", get(runtime_setup_detect))
        .route("/runtime/setup/verify", post(runtime_setup_verify))
        .route("/runtime/setup/ack", post(runtime_setup_ack))
        .route("/runtime/providers/catalog", get(runtime_providers_catalog))
        .route("/runtime/connectors/catalog", get(runtime_connectors_catalog))
        // Auth runs before any handler. `from_fn_with_state` hands the token
        // to the middleware so it can compare in constant time.
        .layer(middleware::from_fn_with_state(state.clone(), require_token))
        .with_state(state)
        .layer(cors)
        // B1 spec gate — per-response `X-Cinderpaw-Api-Stability: stable|unstable`.
        // The middleware is the single point that decides stability from the
        // request path: `/api/*` + `/v1/*` (Ollama/OpenAI-compat aliases) are
        // the only stable surface; everything else is `unstable` pre-2.0
        // (decision recorded in `docs/API.md`). The header is added on every
        // response — including 401s — so clients know the surface they tried
        // is still unstable even if their token was wrong. The middleware
        // sits as the outermost layer so it observes the final response
        // shape after auth + CORS.
        .layer(middleware::from_fn(api_stability_header))
}

/// B1 spec gate. Adds `X-Cinderpaw-Api-Stability: <stable|unstable>` on every
/// response based on the request path. See `docs/API.md` for the canonical
/// list.
///
/// Stable prefixes (Ollama + OpenAI compat only — these are the third-party
/// protocol surfaces):
///   * `/api/`  — Ollama-compatible.
///   * `/v1/`   — OpenAI-compatible.
///
/// Everything else, including `/tokenize` (llama.cpp-server sidecar helper),
/// the runtime/governance/modules/meta surfaces, `/events`, `/system_info`,
/// `/providers/test`, `/runtime/*`, `/meta/*`, `/governance/*`, `/modules/*`
/// — is `unstable` until v2.0.
async fn api_stability_header(req: Request<axum::body::Body>, next: Next) -> Response {
    let path = req.uri().path();
    let stability = if path.starts_with("/api/") || path.starts_with("/v1/") {
        "stable"
    } else {
        "unstable"
    };
    let mut response = next.run(req).await;
    response.headers_mut().insert(
        HeaderName::from_static("x-feral-api-stability"),
        HeaderValue::from_static(stability),
    );
    response
}

/// Reject any request without a valid bearer token. CORS preflight
/// (`OPTIONS`) is allowed through so browsers can negotiate before the real
/// request carries the `Authorization` header.
async fn require_token(
    State(state): State<ApiState>,
    req: Request<axum::body::Body>,
    next: Next,
) -> Response {
    if req.method() == axum::http::Method::OPTIONS {
        return next.run(req).await;
    }
    let presented = req
        .headers()
        .get(header::AUTHORIZATION)
        .and_then(|v| v.to_str().ok())
        .and_then(|v| v.strip_prefix("Bearer "))
        .map(str::trim)
        .unwrap_or("");
    if constant_time_eq(presented.as_bytes(), state.token.as_bytes()) {
        next.run(req).await
    } else {
        (StatusCode::UNAUTHORIZED, "missing or invalid bearer token").into_response()
    }
}

/// Length-independent byte comparison. Localhost timing attacks are a stretch,
/// but a token check is exactly the place to not get cute — the cost is one
/// XOR per byte.
fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    // No early return on a length mismatch: answering "wrong length" faster
    // than "wrong bytes" hands an attacker the real token's length for free.
    // The zip walks min(len) bytes either way, and the length equality is
    // folded into the verdict AFTER the loop instead of before it.
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0 && a.len() == b.len()
}

/// True only when `origin` is exactly a loopback origin — scheme, host, and
/// then either a port or nothing at all.
///
/// `starts_with("http://localhost")` also matches `http://localhost.evil.com`,
/// which is a domain an attacker can register and point anywhere. The bearer
/// token still gates every route behind this, so the bypass was not a breach
/// on its own — but a CORS allowlist that accepts a stranger's origin is one
/// bug away from being one, and the exact check is no longer code.
fn is_loopback_origin(origin: &[u8]) -> bool {
    for host in [&b"http://localhost"[..], &b"http://127.0.0.1"[..]] {
        if let Some(rest) = origin.strip_prefix(host) {
            // Nothing after the host, or a port. `.evil.com` is neither.
            if rest.is_empty() || rest[0] == b':' {
                return true;
            }
        }
    }
    false
}

pub async fn serve(state: ApiState, port: u16) -> anyhow::Result<()> {
    // Loopback only — see module docstring. Binding to 0.0.0.0 here exposed
    // model deletion and inference to every host on the network.
    let addr = format!("127.0.0.1:{}", port);
    let listener = tokio::net::TcpListener::bind(&addr).await?;
    serve_on(state, listener).await
}

/// Serve on a listener somebody else already bound.
///
/// The gateway uses the API port as its single-instance lock: it binds, sees
/// the port is free, then drops the socket so the real server can take it. In
/// the gap between the drop and the re-bind the port belongs to nobody, and
/// whoever grabs it first wins — so the guard could say "clear" and the server
/// still die on "address in use". Handing the listener over closes the gap:
/// the port is never released at all.
pub async fn serve_on(state: ApiState, listener: tokio::net::TcpListener) -> anyhow::Result<()> {
    let app = router(state);
    if let Ok(addr) = listener.local_addr() {
        tracing::info!(%addr, "feral api listening (loopback, token-gated)");
    }
    axum::serve(listener, app).await?;
    Ok(())
}

async fn api_tags() -> impl IntoResponse {
    let models = models::scan_models_dir().unwrap_or_default();
    let items: Vec<Value> = models.into_iter().map(|m| {
        json!({
            "name": m.name,
            "model": m.id,
            "size": m.size_bytes,
            "details": {
                "quantization_level": m.quant,
                "format": "gguf",
            }
        })
    }).collect();
    Json(json!({ "models": items }))
}

#[derive(Deserialize)]
struct ShowReq { name: String }

async fn api_show(Json(req): Json<ShowReq>) -> impl IntoResponse {
    let models = models::scan_models_dir().unwrap_or_default();
    match models.into_iter().find(|m| m.name == req.name || m.id == req.name) {
        Some(m) => Json(json!({
            "model": m.name,
            "size": m.size_bytes,
            "quant": m.quant,
            "modelfile": m.modelfile,
        })).into_response(),
        None => (StatusCode::NOT_FOUND, "not found").into_response(),
    }
}

#[derive(Deserialize)]
struct DeleteReq { name: String }

async fn api_delete(Json(req): Json<DeleteReq>) -> impl IntoResponse {
    let models_dir = crate::paths::models_dir();
    let path = match resolve_model_path_secure(&models_dir, &req.name) {
        Some(p) => p,
        None => return (StatusCode::BAD_REQUEST, "invalid or unsafe model name").into_response(),
    };
    match models::delete_model(&path) {
        Ok(_) => StatusCode::NO_CONTENT.into_response(),
        Err(e) => {
            tracing::warn!(path=%path.display(), error=%e, "api_delete failed");
            (StatusCode::NOT_FOUND, "model not found or could not be deleted").into_response()
        }
    }
}

/// Resolve a caller-supplied model name to a path inside `models_dir`, or
/// `None` if the name is not a safe, contained filename.
///
/// Three layers of defense:
///   1. Reject anything that isn't a bare filename — empty, containing a path
///      separator, a `..` component, or an absolute/rooted path. This blocks
///      the obvious `../../etc/passwd` and `C:\Windows\...` shapes before any
///      filesystem call.
///   2. Confirm the joined path's parent canonicalizes to the models
///      directory. This catches anything the first check missed (symlinks,
///      platform-specific quirks) by comparing real on-disk locations.
///   3. After canonicalizing the *final* path, verify it still starts with
///      the canonical models directory. This defends against TOCTOU races
///      and symlink tricks that swap targets between the parent check and
///      the actual operation.
fn resolve_model_path_secure(models_dir: &std::path::Path, name: &str) -> Option<std::path::PathBuf> {
    let name = name.trim();
    if name.is_empty() {
        return None;
    }
    let candidate = std::path::Path::new(name);
    // Must be exactly one normal path component (the filename itself).
    let mut comps = candidate.components();
    let only = match (comps.next(), comps.next()) {
        (Some(std::path::Component::Normal(c)), None) => c,
        _ => return None,
    };
    if only != std::ffi::OsStr::new(name) {
        return None;
    }
    // Canonicalize the models directory; if it doesn't exist there's nothing to delete.
    let real_dir = models_dir.canonicalize().ok()?;
    let path = models_dir.join(only);
    // Containment check #1: the parent of the candidate must *be* the real models dir.
    let real_parent = path.parent()?.canonicalize().ok()?;
    if real_parent != real_dir {
        return None;
    }
    // Containment check #2 (defense in depth): if the file itself exists,
    // its canonical path must still start with the real models directory.
    if let Ok(real_path) = path.canonicalize() {
        if !real_path.starts_with(&real_dir) {
            return None;
        }
    }
    Some(path)
}

#[derive(Deserialize)]
struct GenerateReq {
    model: String,
    prompt: String,
    #[serde(default)]
    stream: Option<bool>,
    #[serde(default)]
    options: Option<Value>,
    #[serde(default)]
    max_tokens: Option<u32>,
}

async fn api_generate(
    State(state): State<ApiState>,
    Json(req): Json<GenerateReq>,
) -> impl IntoResponse {
    let messages = vec![Message { role: "user".into(), content: req.prompt, images: None }];
    let mut params = params_from_options(req.options.as_ref());
    apply_max_tokens(&mut params, req.max_tokens);

    if req.stream.unwrap_or(true) {
        sse_from_chat(state, req.model, messages, params, false).into_response()
    } else {
        let text = collect_chat(&state, messages, params).await;
        Json(json!({
            "model": req.model,
            "response": text,
            "done": true,
        })).into_response()
    }
}

/// OpenAI-compatible message content: either a plain string or an array of
/// content parts (`[{ "type": "text", "text": "..." }, ...]`). OpenAI-spec
/// clients send the array form; llama.cpp only needs the text.
#[derive(Deserialize)]
#[serde(untagged)]
enum FlexContent {
    Text(String),
    Parts(Vec<ContentPart>),
}

#[derive(Deserialize)]
struct ContentPart {
    #[serde(default)]
    text: Option<String>,
}

impl FlexContent {
    /// Flatten to a single string. Array parts are concatenated; non-text
    /// parts (images, etc.) contribute nothing since llama.cpp is text-only.
    fn into_string(self) -> String {
        match self {
            FlexContent::Text(s) => s,
            FlexContent::Parts(parts) => parts
                .into_iter()
                .filter_map(|p| p.text)
                .collect::<Vec<_>>()
                .join(""),
        }
    }
}

#[derive(Deserialize)]
struct ApiMessage {
    role: String,
    #[serde(default)]
    content: Option<FlexContent>,
}

impl From<ApiMessage> for Message {
    fn from(m: ApiMessage) -> Self {
        Message {
            role: m.role,
            content: m.content.map(FlexContent::into_string).unwrap_or_default(),
            images: None,
        }
    }
}

#[derive(Deserialize)]
struct ChatReq {
    model: String,
    messages: Vec<ApiMessage>,
    #[serde(default)]
    stream: Option<bool>,
    #[serde(default)]
    options: Option<Value>,
    /// OpenAI-standard generation cap. OpenAI-spec clients send this at the
    /// top level (not nested under `options`). Without honoring it, every
    /// agent request fell back to the 1024-token default and ran for
    /// minutes of CPU inference, appearing to hang.
    #[serde(default)]
    max_tokens: Option<u32>,
    /// Cinderpaw extension: a GBNF grammar that constrains decoding. The agent
    /// sidecar sends this to force valid tool-call JSON (grammar-constrained
    /// decoding). Standard OpenAI clients omit it and get unconstrained output.
    #[serde(default)]
    grammar: Option<String>,
    /// Cinderpaw extension: trigger strings for lazy grammar enforcement (see
    /// `InferParams::grammar_triggers`). The grammar engages only after one of
    /// these appears, so prose stays unconstrained and only the tool call is.
    #[serde(default)]
    grammar_triggers: Option<Vec<String>>,
    /// Cinderpaw extension (P1 — prompt caching): caller-supplied session id
    /// threaded into the audit log so a row can be cross-referenced with
    /// what the user saw. The bundled llama.cpp engine draws contexts from
    /// a small pool (P6); each context keeps its own KV prefix-diff record,
    /// and reuse is opportunistic — a caller that lands on a context whose
    /// cache shares its prefix benefits, regardless of session id. The
    /// field is plumbed through now so a future session→context affinity
    /// strategy can be added without another breaking schema change.
    #[serde(default)]
    session_id: Option<String>,
}

impl ChatReq {
    /// Convert incoming OpenAI-style messages into Cinderpaw's internal `Message`.
    fn into_messages(self) -> Vec<Message> {
        self.messages.into_iter().map(Message::from).collect()
    }
}

/// One lazy-load at a time — a burst of eval requests must not stack up N
/// concurrent `manager.load` calls for the same model.
static API_AUTOLOAD_IN_FLIGHT: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

/// Ensure a model is loaded before serving a completion.
///
/// Boot auto-load was deliberately removed (2026-06-30: mmap lag froze
/// non-technical users' machines), so nothing guarantees a loaded model when
/// an API caller arrives — connectors hit that hole across a restart, since
/// nothing reloads the model the user picked last session.
///
/// This loads lazily, on first demand, but ONLY a model the user actually
/// chose: the id the caller named, or their persisted `active_route`. It used
/// to fall back to "the first model on disk", which meant any caller could make
/// the app pull a multi-GB GGUF the user had never selected — a cloud-only user
/// paid ~5 GB of RSS for it (2026-07-13). Choosing a model is the user's call;
/// no model chosen → 503, never a guess.
///
/// Waits out a concurrent load (UI or another request) up to
/// `FERAL_MODEL_WAIT_MS` (default 120s).
/// Which model may we load for this request? Only one the user chose: the id
/// they named, else the one they last selected (`chosen`, from `active_route`).
/// Deliberately has NO "first model on disk" arm — that arm is what let any
/// caller pull a multi-GB GGUF the user never picked.
fn pick_user_model<'a>(
    models: &'a [models::ModelInfo],
    requested: &str,
    chosen: Option<&str>,
) -> Option<&'a models::ModelInfo> {
    let by = |want: &str| models.iter().find(|m| m.id == want || m.name == want);
    by(requested).or_else(|| chosen.and_then(by))
}

async fn wait_for_model(state: &ApiState, requested: &str) -> bool {
    use std::sync::atomic::Ordering;
    if state.manager.current().is_some() {
        return true;
    }

    if !API_AUTOLOAD_IN_FLIGHT.swap(true, Ordering::SeqCst) {
        // We own the load. Resolve against what the USER picked — never a guess.
        let requested = requested.to_string();
        // Their last explicit selection, persisted by the UI / `POST /model` /
        // guided setup. Survives a restart, which is what keeps connectors
        // working without a boot-time load.
        let chosen = crate::settings::load().active_route.and_then(|r| {
            r.split_once(':')
                .filter(|(pid, _)| *pid == "local")
                .map(|(_, name)| name.to_string())
        });
        let manager = state.manager.clone();
        // Clears the flag however this scope ends — including the case that made
        // the flag a permanent outage: the client disconnects, axum drops this
        // handler future mid-`.await`, the store below never runs, and every
        // later request takes the 120s wait path and 503s until the gateway is
        // restarted. A drop guard is the only reset that survives cancellation.
        struct ClearOnDrop;
        impl Drop for ClearOnDrop {
            fn drop(&mut self) {
                API_AUTOLOAD_IN_FLIGHT.store(false, std::sync::atomic::Ordering::SeqCst);
            }
        }
        let _clear = ClearOnDrop;
        let loaded = tokio::task::spawn_blocking(move || {
            let models = models::scan_models_dir().unwrap_or_default();
            let pick = pick_user_model(&models, &requested, chosen.as_deref());
            match pick {
                Some(m) => {
                    tracing::info!(model = %m.id, "api: lazy-loading the user's selected model on first completion request");
                    // n_gpu_layers -1 = offload all (GPU builds fall back to
                    // CPU internally); context uses the conservative default
                    // cap — the UI's Hardware choice re-applies on its next
                    // explicit load.
                    manager.load(m.path.clone(), -1, None).map(|_| true).unwrap_or(false)
                }
                None => {
                    tracing::info!("api: no model loaded and none selected — refusing to pick one for the user");
                    false
                }
            }
        })
        .await
        .unwrap_or(false);
        drop(_clear);
        if loaded {
            return true;
        }
        // Fall through to the wait loop — a concurrent UI load may still land.
    }

    let deadline_ms = crate::env::env_var("FERAL_MODEL_WAIT_MS")
        .and_then(|v| v.trim().parse::<u64>().ok())
        .unwrap_or(120_000);
    let start = std::time::Instant::now();
    while start.elapsed().as_millis() < u128::from(deadline_ms) {
        if state.manager.current().is_some() {
            return true;
        }
        if !API_AUTOLOAD_IN_FLIGHT.load(Ordering::SeqCst) {
            // No load in flight anymore and still no model → nothing on disk
            // or the load failed; give the caller a real error now.
            if state.manager.current().is_none() {
                return false;
            }
        }
        tokio::time::sleep(std::time::Duration::from_millis(500)).await;
    }
    false
}

/// The 503 body both chat endpoints return when `wait_for_model` gives up.
/// A real status code (not an empty 200) lets the sidecar's router treat it
/// as a failed call it can surface, instead of a silent empty response.
fn no_model_response() -> axum::response::Response {
    (
        StatusCode::SERVICE_UNAVAILABLE,
        Json(json!({ "error": {
            "message": "no model selected — choose one in Models (or name an installed model in the request)",
            "type": "model_not_ready",
        } })),
    )
        .into_response()
}

async fn api_chat(
    State(state): State<ApiState>,
    Json(req): Json<ChatReq>,
) -> impl IntoResponse {
    if !wait_for_model(&state, &req.model).await {
        return no_model_response();
    }
    let mut params = params_from_options(req.options.as_ref());
    apply_max_tokens(&mut params, req.max_tokens);
    apply_grammar(&mut params, &req);
    apply_session(&mut params, &req);
    let model = req.model.clone();
    let stream = req.stream.unwrap_or(true);
    let messages = req.into_messages();
    if stream {
        sse_from_chat(state, model, messages, params, false).into_response()
    } else {
        let text = collect_chat(&state, messages, params).await;
        Json(json!({
            "model": model,
            "message": { "role": "assistant", "content": text },
            "done": true,
        })).into_response()
    }
}

#[derive(Deserialize)]
struct TokenizeReq {
    content: String,
    /// Accepted for llama.cpp-server compatibility; tokenization always uses
    /// the currently loaded model.
    #[serde(default)]
    #[allow(dead_code)]
    model: Option<String>,
}

/// Count tokens with the loaded model's tokenizer. Returns `{"count": n}` —
/// the sidecar's `tokenizeLocal()` accepts either a `tokens` array or a
/// `count`; sending only the count avoids serializing thousands of ids for
/// long prompts.
async fn api_tokenize(
    State(state): State<ApiState>,
    Json(req): Json<TokenizeReq>,
) -> impl IntoResponse {
    match state.manager.count_tokens(&req.content) {
        Ok(n) => Json(json!({ "count": n })).into_response(),
        Err(e) => (StatusCode::SERVICE_UNAVAILABLE, e.to_string()).into_response(),
    }
}

async fn v1_models() -> impl IntoResponse {
    let models = models::scan_models_dir().unwrap_or_default();
    let data: Vec<Value> = models.into_iter().map(|m| {
        json!({ "id": m.id, "object": "model", "owned_by": "feral" })
    }).collect();
    Json(json!({ "object": "list", "data": data }))
}

// ── Public Runtime API v1 (Faza 4.5 Slice 3) ──────────────────────────────
//
// All handlers here read from `state.runtime` (the host-agnostic RuntimeState)
// so every host — desktop or headless gateway — serves identical answers
// (invariant 11). Nothing here fabricates: fields the runtime cannot source
// locally (connectors/memories/dreams live in the sidecar) are reported as
// `null` until the sidecar-round-trip vertical wires them.

#[derive(Deserialize)]
struct RuntimeChatReq {
    /// The user's new message. The sidecar owns per-session history (unified
    /// memory, invariant 11), so we forward only the new turn, not a transcript.
    content: String,
    /// Session key. Every client that shares a `session_id` shares one
    /// conversation + memory. Defaults to `api` per spec D3.
    #[serde(default = "default_session")]
    session_id: String,
    /// SSE token stream (default) vs a single JSON reply.
    #[serde(default = "default_true")]
    stream: bool,
}
fn default_session() -> String { "api".to_string() }
fn default_true() -> bool { true }

/// How long to wait for the next reply fragment before giving up. Local
/// inference plus a tool call can be slow; 120s idle is generous without
/// hanging a dead sidecar's socket open forever.
const CHAT_IDLE_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(120);

/// D3: forward a chat turn to the supervised sidecar and stream the reply.
///
/// The sidecar broadcasts *all* output on one bus as `cinderpaw://agent-output`
/// events (no per-request socket), so we correlate our reply by the message
/// `id` we generate: subscribe to the bus BEFORE sending (no lost-first-token
/// race), send `{"type":"message", id, content, sessionId}`, then keep only
/// `chunk`/`done` events whose `id` matches ours. Same session, same memory,
/// same LoRA, same tools as the desktop and the connectors — this is just
/// another face on the one brain.
/// How long a voice tool may take before the caller is given something to say.
///
/// A budget for ANSWERING, not for working. The agent's own reply timeout is
/// two minutes, and a realtime session blocks on a tool call — so without this
/// the model announces "let me look that up" and then goes silent for up to two
/// minutes, which is indistinguishable from the app having died. Twenty seconds
/// is about the longest anyone holds a phone to their ear hearing nothing.
///
/// Forty-five, not the twenty this and the old engine both used, because
/// twenty was measured against SILENCE and the caller is no longer silent: the
/// tool declaration tells the model to keep talking while it waits. What twenty
/// actually bought was a second round trip. Real spoken questions timed on
/// 2026-08-24 took 10.7s, 9.8s and over 20s, so the commonest thing a call
/// reaches for — a web search — sat right on the line. Past the deadline the
/// model is handed "still working" and has to ask AGAIN, and the re-ask is
/// keyed on the exact request string: rephrase one word while asking twice and
/// the entire search starts from nothing. Waiting once beats restarting.
const VOICE_TOOL_DEADLINE: std::time::Duration = std::time::Duration::from_secs(45);

/// Work that outlived its deadline, keyed by the request that started it.
///
/// Two jobs, both only visible on a call that lasts. The model is free again
/// the moment it gets a holding reply, and the obvious thing for it to do is
/// ask the same question again — which without this starts a SECOND copy of a
/// job already running, then a third. And when the slow answer does arrive,
/// somebody has to be holding it, or the work was wasted.
static VOICE_IN_FLIGHT: std::sync::OnceLock<
    parking_lot::Mutex<std::collections::HashMap<String, tokio::sync::watch::Receiver<Option<String>>>>,
> = std::sync::OnceLock::new();

fn voice_in_flight(
) -> &'static parking_lot::Mutex<std::collections::HashMap<String, tokio::sync::watch::Receiver<Option<String>>>> {
    VOICE_IN_FLIGHT.get_or_init(|| parking_lot::Mutex::new(std::collections::HashMap::new()))
}

#[derive(serde::Deserialize)]
struct SpeakRequest {
    /// A TTS engine id from the catalogue — `piper`, `kokoro`, `fish`, …
    provider: String,
    voice: Option<String>,
    text: String,
}

/// Synthesise one utterance and hand back the raw PCM.
///
/// This exists so the LiveKit voice worker can speak in the SAME voices the
/// rest of the app speaks in — Piper and Kokoro run on this machine, and the
/// Romanian voices in `paths::RO_VOICES` exist nowhere else. Without it,
/// choosing LiveKit as the engine meant choosing a cloud vendor, because the
/// worker is a separate Node process with no way to reach an engine that lives
/// in this binary.
///
/// Raw PCM rather than WAV: the caller feeds it straight into an `AudioFrame`,
/// and a header it would only have to strip is a header worth not writing. The
/// sample rate travels in `x-sample-rate` because it is a property of the
/// ENGINE, not a constant — Piper voices are 22.05 kHz and playing those at 24
/// makes the voice fast and high while looking like a working feature.
async fn runtime_voice_speak(
    State(state): State<ApiState>,
    Json(req): Json<SpeakRequest>,
) -> Response {
    // The stored endpoint and model, not just the key. Azure needs a region URL
    // and ElevenLabs needs a voice/model id, so passing `None` for those would
    // offer both engines in the picker and fail every call to them — the same
    // shape as hard-coding Piper, one layer down.
    let byok_settings = crate::byok::load(&state.runtime.settings);
    let stored = byok_settings.get_provider(&req.provider);
    let engine = match crate::tts::from_id(
        &req.provider,
        crate::tts::EngineConfig {
            api_key: &crate::byok::byok_get(&req.provider).unwrap_or_default(),
            base_url: stored.and_then(|c| c.base_url.as_deref()),
            model: stored.and_then(|c| c.default_model.as_deref()),
        },
    ) {
        Ok(e) => e,
        Err(e) => {
            tracing::warn!(engine = %req.provider, error = %e, "voice speak: engine refused");
            return (StatusCode::BAD_REQUEST, e.to_string()).into_response();
        }
    };
    let rate = engine.sample_rate();
    let (tx, mut rx) = tokio::sync::mpsc::channel::<Vec<u8>>(8);
    let request = crate::tts::SpeechRequest { text: req.text, voice: req.voice };
    let synth = tokio::spawn(async move { engine.speak(&request, tx).await });

    // Collected rather than streamed. The utterance is one sentence — the voice
    // pipeline already splits on sentence boundaries before calling — so the
    // latency saved by streaming is under the wire time, while a streaming body
    // would need chunked framing on both sides to say where a sentence ended.
    let mut pcm = Vec::new();
    while let Some(chunk) = rx.recv().await {
        pcm.extend_from_slice(&chunk);
    }
    if let Ok(Err(e)) = synth.await {
        tracing::warn!(error = %e, "voice speak: synthesis failed");
        return (StatusCode::BAD_GATEWAY, e.to_string()).into_response();
    }
    (
        [
            (axum::http::header::CONTENT_TYPE, "application/octet-stream".to_string()),
            (axum::http::HeaderName::from_static("x-sample-rate"), rate.to_string()),
        ],
        pcm,
    )
        .into_response()
}

/// Proper nouns Whisper has never heard, biasing decoding toward the spellings
/// this app uses. "Cinderpaw" came back as Mouth, Molaus, Paula and Mose across
/// one evening of testing, and every miss became a message the agent had to
/// answer as if it were a different word.
pub const STT_PROPER_NOUNS: &str = "Cinderpaw, Cubby, Bloom, Darius, Piper, Kokoro.";

/// 16-bit mono PCM wrapped in a WAV header.
///
/// Written by hand rather than pulled in as a dependency: it is 44 bytes of
/// little-endian fields, and the cloud transcribers want a container rather
/// than a naked buffer. The worker has frames, not files.
fn wav_from_f32(pcm: &[f32], rate: u32) -> Vec<u8> {
    let data_len = (pcm.len() * 2) as u32;
    let mut out = Vec::with_capacity(44 + data_len as usize);
    out.extend_from_slice(b"RIFF");
    out.extend_from_slice(&(36 + data_len).to_le_bytes());
    out.extend_from_slice(b"WAVEfmt ");
    out.extend_from_slice(&16u32.to_le_bytes()); // PCM chunk size
    out.extend_from_slice(&1u16.to_le_bytes()); // format: PCM
    out.extend_from_slice(&1u16.to_le_bytes()); // channels
    out.extend_from_slice(&rate.to_le_bytes());
    out.extend_from_slice(&(rate * 2).to_le_bytes()); // byte rate
    out.extend_from_slice(&2u16.to_le_bytes()); // block align
    out.extend_from_slice(&16u16.to_le_bytes()); // bits per sample
    out.extend_from_slice(b"data");
    out.extend_from_slice(&data_len.to_le_bytes());
    for s in pcm {
        out.extend_from_slice(&((s.clamp(-1.0, 1.0) * 32767.0) as i16).to_le_bytes());
    }
    out
}

/// Transcribe through a hosted recogniser.
///
/// Only Groq is wired, matching `commands::voice::transcribe_audio_cloud` — the
/// same endpoint, model and vocabulary prompt, so a call and a voice message are
/// not transcribed by two subtly different requests.
async fn transcribe_cloud(provider: &str, pcm: &[f32], language: Option<&str>) -> Response {
    let endpoint = match provider {
        "groq" => "https://api.groq.com/openai/v1/audio/transcriptions",
        other => {
            return (StatusCode::BAD_REQUEST, format!("no cloud transcriber called {other:?}"))
                .into_response()
        }
    };
    let Some(key) = crate::byok::byok_get(provider) else {
        // Named, so the worker can say which key is missing rather than
        // reporting that the call cannot hear.
        return (StatusCode::SERVICE_UNAVAILABLE, "stt-no-key").into_response();
    };
    let part = match reqwest::multipart::Part::bytes(wav_from_f32(pcm, 16_000))
        .file_name("audio.wav")
        .mime_str("audio/wav")
    {
        Ok(p) => p,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    };
    let mut form = reqwest::multipart::Form::new()
        .text("model", "whisper-large-v3")
        .text("prompt", STT_PROPER_NOUNS)
        .part("file", part);
    if let Some(lang) = language.map(str::trim).filter(|l| !l.is_empty()) {
        form = form.text("language", lang.to_string());
    }
    let res = reqwest::Client::new()
        .post(endpoint)
        .bearer_auth(key)
        .multipart(form)
        .timeout(std::time::Duration::from_secs(60))
        .send()
        .await;
    match res {
        Ok(r) if r.status().is_success() => match r.json::<serde_json::Value>().await {
            Ok(v) => Json(serde_json::json!({
                "text": v.get("text").and_then(|t| t.as_str()).unwrap_or_default()
            }))
            .into_response(),
            Err(e) => (StatusCode::BAD_GATEWAY, e.to_string()).into_response(),
        },
        Ok(r) => {
            let code = r.status();
            let why = r.text().await.unwrap_or_default();
            tracing::warn!(%code, "voice transcribe: cloud refused");
            (StatusCode::BAD_GATEWAY, format!("stt-cloud-failed: {}", why)).into_response()
        }
        Err(e) => (StatusCode::BAD_GATEWAY, format!("stt-cloud-failed: {e}")).into_response(),
    }
}

#[derive(serde::Deserialize)]
struct TranscribeRequest {
    /// 16 kHz mono f32, which is what Whisper wants and what the worker
    /// resamples to before sending.
    pcm: Vec<f32>,
    #[serde(default)]
    model_size: Option<String>,
    /// `local` (Whisper on this machine) or a cloud id such as `groq`.
    #[serde(default)]
    provider: Option<String>,
    /// ISO-639-1 hint. Whisper treats it as an OVERRIDE, so it is only ever the
    /// caller's explicit choice — feeding back what was detected last time made
    /// the loop self-sealing, and a user switching language could never be
    /// heard again.
    #[serde(default)]
    language: Option<String>,
}

/// Transcribe one utterance on this machine.
///
/// The counterpart of `runtime_voice_speak`, and the other half of a call that
/// never leaves the device. `model-missing` is returned by name rather than as
/// prose: the worker turns it into a sentence telling the person to download
/// the model, and a message assembled here would be a second place to
/// translate it.
async fn runtime_voice_transcribe(
    State(_state): State<ApiState>,
    Json(req): Json<TranscribeRequest>,
) -> Response {
    // A cloud transcriber is a different door, and it is checked first: falling
    // through to the local branch when a key is missing would transcribe on the
    // machine while the screen said Groq, which is the screen lying about where
    // somebody's voice went.
    let provider = req.provider.as_deref().unwrap_or("local");
    if provider != "local" {
        return transcribe_cloud(provider, &req.pcm, req.language.as_deref()).await;
    }
    let size = req.model_size.unwrap_or_else(|| "small".into());
    let model_path = crate::paths::whisper_model_path(&size);
    if !model_path.exists() {
        return (StatusCode::SERVICE_UNAVAILABLE, "model-missing").into_response();
    }
    #[cfg(feature = "whisper")]
    {
        let pcm = req.pcm;
        // Whisper is CPU-bound; keep it off the async runtime's threads or the
        // API server stops answering for the length of every utterance.
        let out = tokio::task::spawn_blocking(move || {
            crate::transcription::transcribe_pcm(&pcm, &model_path)
        })
        .await;
        return match out {
            Ok(Ok(text)) => Json(serde_json::json!({ "text": text })).into_response(),
            Ok(Err(e)) => (StatusCode::BAD_GATEWAY, e.to_string()).into_response(),
            Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
        };
    }
    #[cfg(not(feature = "whisper"))]
    {
        let _ = req.pcm;
        // Named, not silently empty. A build without Whisper cannot transcribe
        // at all, and an empty transcript would look like a person who said
        // nothing rather than a build that cannot listen.
        (StatusCode::SERVICE_UNAVAILABLE, "voice-unavailable").into_response()
    }
}

/// One tool call from a voice session, answered by the local agent.
///
/// This grants no capability the token did not already grant — `/runtime/chat`
/// reaches the same agent with the same tools. What it adds is the shape the
/// realtime model needs: a single request, a single answer, a name for the door
/// (`ask_cinder`) rather than a chat turn, and a deadline, because the caller
/// is a person waiting in silence rather than a script.
async fn runtime_voice_tool(
    State(state): State<ApiState>,
    Json(call): Json<crate::live::FunctionCall>,
) -> Response {
    let request =
        call.args.get("request").and_then(|v| v.as_str()).unwrap_or_default().trim().to_lowercase();
    let started = std::time::Instant::now();
    // Logged on the way in as well as out. A tool call used to leave no trace
    // at all, so "did it even try to search?" had no answer anywhere — and that
    // is the first question when a spoken answer sounds invented.
    tracing::info!(tool = %call.name, request = %request, "voice tool: asked");

    // Already running? Wait on that one rather than starting another.
    let existing = voice_in_flight().lock().get(&request).cloned();
    let mut rx = match existing {
        Some(rx) => rx,
        None => {
            let (tx, rx) = tokio::sync::watch::channel(None);
            voice_in_flight().lock().insert(request.clone(), rx.clone());
            let runtime = state.runtime.clone();
            let call = call.clone();
            let key = request.clone();
            tokio::spawn(async move {
                let session = format!("voice-{}", call.id);
                let answered =
                    crate::live::bridge::answer(&call, Some(&runtime), &session).await;
                let _ = tx.send(Some(answered.response.to_string()));
                // Kept briefly after finishing so a model that asks again right
                // away gets the answer instead of restarting the work.
                tokio::time::sleep(std::time::Duration::from_secs(30)).await;
                voice_in_flight().lock().remove(&key);
            });
            rx
        }
    };

    let waited = tokio::time::timeout(VOICE_TOOL_DEADLINE, async {
        loop {
            if let Some(done) = rx.borrow_and_update().clone() {
                return done;
            }
            if rx.changed().await.is_err() {
                return String::new();
            }
        }
    })
    .await;

    let response = match waited {
        Ok(body) if !body.is_empty() => {
            tracing::info!(ms = started.elapsed().as_millis() as u64, "voice tool: answered");
            serde_json::from_str::<serde_json::Value>(&body)
                .unwrap_or_else(|_| json!({ "ok": true, "output": body }))
        }
        _ => {
            // Not an error: the work is still running, and the model needs a
            // sentence it can say out loud rather than a silence.
            tracing::info!(
                ms = started.elapsed().as_millis() as u64,
                "voice tool: still running past the deadline, holding reply sent"
            );
            json!({
                "ok": false,
                "output": "Still working on that one — it is taking longer than usual.                            Tell the user you are still on it, and ask again in a moment."
            })
        }
    };

    Json(json!({ "id": call.id, "response": response })).into_response()
}

async fn runtime_chat(
    State(state): State<ApiState>,
    Json(req): Json<RuntimeChatReq>,
) -> Response {
    let rt = &state.runtime;

    // Grab the sidecar sender without holding the lock across the await.
    let tx = {
        let guard = rt.cinderpaw_agent_tx.lock();
        match guard.as_ref() {
            Some(tx) => tx.clone(),
            None => {
                return (StatusCode::SERVICE_UNAVAILABLE, "feral-agent sidecar is not running")
                    .into_response()
            }
        }
    };

    let msg_id = uuid::Uuid::new_v4().to_string();
    // Subscribe BEFORE sending so we can't miss the first chunk.
    let rx = rt.events_tx.subscribe();

    let outbound = json!({
        "type": "message",
        "id": msg_id,
        "content": req.content,
        "sessionId": req.session_id,
    })
    .to_string();
    if tx.send(outbound).await.is_err() {
        return (StatusCode::SERVICE_UNAVAILABLE, "feral-agent sidecar stopped accepting messages")
            .into_response();
    }

    if req.stream {
        sse_from_agent_reply(rx, msg_id, req.session_id.clone()).into_response()
    } else {
        // Non-stream: the `done` event already carries the full text, so we
        // just wait for our matching `done` instead of accumulating chunks.
        match await_agent_reply(rx, &msg_id).await {
            Ok(text) => Json(json!({
                "id": msg_id,
                "session_id": req.session_id,
                "content": text,
            }))
            .into_response(),
            Err(e) => (StatusCode::GATEWAY_TIMEOUT, e).into_response(),
        }
    }
}

/// Pull one line's `type`+`id`+`content` out of a `cinderpaw://agent-output`
/// broadcast event, if it is one. The payload is `{"data": "<json line>"}`
/// where the line is itself the sidecar's JSON event.
///
/// For tool events we also surface the structured fields (tool name, args,
/// progress message, result) so the SSE layer can re-emit them as typed
/// `event:` lines — see `sse_from_agent_reply`.
fn parse_agent_output(ev: &crate::host::HostEvent) -> Option<AgentOutputLine> {
    if ev.event != "cinderpaw://agent-output" {
        return None;
    }
    let line = ev.payload.get("data")?.as_str()?;
    let v: Value = serde_json::from_str(line).ok()?;
    let ty = v.get("type")?.as_str()?.to_string();
    let id = v.get("id").and_then(|x| x.as_str()).unwrap_or("").to_string();
    // `chunk`/`done` carry the text in `content`; `error` carries it in
    // `message`. Fall back so the correlator can surface failures too.
    let content = v
        .get("content")
        .and_then(|x| x.as_str())
        .or_else(|| v.get("message").and_then(|x| x.as_str()))
        .unwrap_or("")
        .to_string();
    Some(AgentOutputLine {
        ty,
        id,
        content,
        raw: v,
    })
}

/// Flattened one-line view of a `cinderpaw://agent-output` payload, with the
/// original `Value` retained so tool events can be re-serialised with their
/// structured fields intact (`tool_start.tool`, `tool_done.result`, …).
///
/// `Debug` and `PartialEq` are derived so the test module below can use
/// `assert_eq!`; the `Value` in `raw` participates in equality via serde_json's
/// `Value` impls, which is fine because the fields are deterministic for
/// each input.
#[derive(Debug, PartialEq)]
struct AgentOutputLine {
    ty: String,
    id: String,
    content: String,
    raw: Value,
}

/// Wait for the `done` event matching `msg_id`, returning its full text.
/// Used by the non-stream path.
/// `pub(crate)` for the Live bridge: a speech-to-speech call reaches Cinderpaw's
/// tools by putting a request to the agent and speaking what comes back, which
/// is the same round trip `/runtime/chat` already makes. Re-implementing the
/// wait would mean two definitions of "the reply finished".
pub(crate) async fn await_agent_reply(
    mut rx: broadcast::Receiver<crate::host::HostEvent>,
    msg_id: &str,
) -> Result<String, String> {
    loop {
        match tokio::time::timeout(CHAT_IDLE_TIMEOUT, rx.recv()).await {
            Ok(Ok(ev)) => {
                if let Some(line) = parse_agent_output(&ev) {
                    if line.id == msg_id {
                        match line.ty.as_str() {
                            "done" => return Ok(line.content),
                            "error" => return Err(format!("sidecar inference error: {}", line.content)),
                            _ => {}
                        }
                    }
                }
            }
            Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
            Ok(Err(broadcast::error::RecvError::Closed)) => {
                return Err("runtime event bus closed before reply completed".into())
            }
            Err(_) => return Err("timed out waiting for sidecar reply".into()),
        }
    }
}

/// SSE the reply for `msg_id` as OpenAI-style chat chunks (so any OpenAI SSE
/// client — and `feral chat` — can consume it), terminating with `[DONE]`.
///
/// `tool_start` / `tool_progress` / `tool_done` events matching `msg_id` are
/// re-emitted as **typed SSE events** (separate `event:` lines, not on
/// `data:`) so plain OpenAI clients ignore them while tool-aware clients
/// (`feral chat`, future agents) can render a tool-call stream without
/// polluting the answer text.
fn sse_from_agent_reply(
    rx: broadcast::Receiver<crate::host::HostEvent>,
    msg_id: String,
    session_id: String,
) -> Sse<impl Stream<Item = Result<Event, Infallible>>> {
    use async_stream::stream;
    let s = stream! {
        let mut rx = rx;
        loop {
            let recv = tokio::time::timeout(CHAT_IDLE_TIMEOUT, rx.recv()).await;
            match recv {
                Ok(Ok(ev)) => {
                    let Some(line) = parse_agent_output(&ev) else { continue };
                    // ask_user carries its own request uuid (not the chat
                    // msg_id) and correlates by SESSION — forward it before
                    // the id guard so terminal clients can render the
                    // question and answer via POST /runtime/ask/respond.
                    if line.ty == "ask_user" || line.ty == "ask_user_cancelled" {
                        let sid = line.raw.get("sessionId").and_then(|s| s.as_str()).unwrap_or("");
                        if sid == session_id {
                            yield Ok::<_, Infallible>(Event::default()
                                .event(line.ty.clone())
                                .data(line.raw.to_string()));
                        }
                        continue;
                    }
                    if line.id != msg_id { continue; }
                    match line.ty.as_str() {
                        "chunk" => {
                            let payload = json!({
                                "id": format!("chatcmpl-{msg_id}"),
                                "object": "chat.completion.chunk",
                                "choices": [{ "index": 0, "delta": { "content": line.content } }],
                            });
                            yield Ok::<_, Infallible>(Event::default().data(payload.to_string()));
                        }
                        "done" => {
                            let payload = json!({
                                "id": format!("chatcmpl-{msg_id}"),
                                "object": "chat.completion.chunk",
                                "choices": [{ "index": 0, "delta": {}, "finish_reason": "stop" }],
                            });
                            yield Ok(Event::default().data(payload.to_string()));
                            yield Ok(Event::default().data("[DONE]"));
                            break;
                        }
                        "tool_start" => {
                            // Re-serialise the raw event with the original id
                            // embedded — the sidecar emits `id` per call, and
                            // clients correlate tool_start → tool_done by it.
                            yield Ok(Event::default()
                                .event("tool_start")
                                .data(line.raw.to_string()));
                        }
                        "tool_progress" => {
                            yield Ok(Event::default()
                                .event("tool_progress")
                                .data(line.raw.to_string()));
                        }
                        "tool_done" => {
                            yield Ok(Event::default()
                                .event("tool_done")
                                .data(line.raw.to_string()));
                        }
                        "error" => {
                            // Surface the sidecar's inference error to the client
                            // instead of hanging until the idle timeout.
                            tracing::warn!(msg_id = %msg_id, error = %line.content, "/runtime/chat sidecar error");
                            let payload = json!({
                                "id": format!("chatcmpl-{msg_id}"),
                                "object": "chat.completion.chunk",
                                "choices": [{ "index": 0, "delta": {}, "finish_reason": "error" }],
                                "error": line.content,
                            });
                            yield Ok(Event::default().data(payload.to_string()));
                            yield Ok(Event::default().data("[DONE]"));
                            break;
                        }
                        _ => {} // usage / budget_warning / etc. — metadata, not text or tool
                    }
                }
                Ok(Err(broadcast::error::RecvError::Lagged(n))) => {
                    tracing::warn!(skipped = n, "/runtime/chat subscriber lagged");
                    continue;
                }
                Ok(Err(broadcast::error::RecvError::Closed)) => break,
                Err(_) => {
                    // Idle timeout — close the stream rather than hang.
                    tracing::warn!(msg_id = %msg_id, "/runtime/chat idle timeout");
                    yield Ok(Event::default().data("[DONE]"));
                    break;
                }
            }
        }
    };
    Sse::new(s)
}

/// `POST /runtime/ask/respond` — body: {requestId, answers}. Answers a
/// pending `ask_user` question (forwarded on the chat SSE stream as a typed
/// `ask_user` event). Fire-and-forget: the sidecar's AskUserBridge resolves
/// the tool call and the agent turn continues on the original stream.
async fn runtime_ask_respond(
    State(state): State<ApiState>,
    body: Option<Json<Value>>,
) -> Response {
    let Some(Json(v)) = body else {
        return (StatusCode::BAD_REQUEST, "body required: {requestId, answers}").into_response();
    };
    let (Some(request_id), Some(answers)) = (
        v.get("requestId").and_then(|x| x.as_str()),
        v.get("answers").filter(|a| a.is_array()),
    ) else {
        return (StatusCode::BAD_REQUEST, "body required: {requestId, answers: []}").into_response();
    };
    let tx = { state.runtime.cinderpaw_agent_tx.lock().as_ref().cloned() };
    let Some(tx) = tx else {
        return (StatusCode::SERVICE_UNAVAILABLE, "feral-agent sidecar is not running")
            .into_response();
    };
    let payload =
        json!({ "type": "ask_user_response", "requestId": request_id, "answers": answers });
    if tx.send(payload.to_string()).await.is_err() {
        return (StatusCode::SERVICE_UNAVAILABLE, "sidecar stopped accepting messages")
            .into_response();
    }
    Json(json!({ "ok": true })).into_response()
}

/// R6: `GET /runtime/connectors` — the redacted state (enabled, which secret
/// fields are filled, allowlist, channels, mode) for every persisted
/// connector. Static catalog metadata (name, pairing fields, icon…) lives at
/// `GET /runtime/connectors/catalog`; join client-side by `id`. Never returns
/// a raw secret value.
async fn runtime_connectors_list() -> Response {
    let views: Vec<_> = connector_catalog::load_connector_configs()
        .iter()
        .map(connector_catalog::redact_for_frontend)
        .collect();
    Json(views).into_response()
}

#[derive(Deserialize)]
struct RuntimeConnectorSaveBody {
    id: String,
    #[serde(default)]
    enabled: Option<bool>,
    #[serde(default)]
    secrets: Option<std::collections::HashMap<String, String>>,
    #[serde(default)]
    allowlist: Option<Vec<String>>,
    #[serde(default)]
    channels: Option<Vec<String>>,
    #[serde(default)]
    mode: Option<String>,
    #[serde(default, rename = "knowledgeBase")]
    knowledge_base: Option<String>,
    #[serde(default)]
    persona: Option<String>,
    #[serde(default, rename = "personaTools")]
    persona_tools: Option<Vec<String>>,
}

/// R6: `POST /runtime/connectors` — upsert one connector's config (only
/// non-empty secret values override existing ones, matching the desktop
/// command's merge semantics), then poke the sidecar to reload — same
/// mechanism as `POST /runtime/connectors/reload`. Returns the redacted view.
async fn runtime_connectors_save(
    State(state): State<ApiState>,
    Json(body): Json<RuntimeConnectorSaveBody>,
) -> Response {
    if connector_catalog::connector_by_id(&body.id).is_none() {
        return (StatusCode::BAD_REQUEST, "unknown connector id").into_response();
    }
    let mut cfg = connector_catalog::load_connector_config(&body.id)
        .unwrap_or_else(|| connector_catalog::blank_connector_config(&body.id));
    if let Some(enabled) = body.enabled {
        cfg.enabled = enabled;
    }
    if let Some(secrets) = body.secrets {
        for (k, v) in secrets {
            let v = v.trim();
            if !v.is_empty() {
                cfg.secrets.insert(k, v.to_string());
            }
        }
    }
    if let Some(allowlist) = body.allowlist {
        cfg.allowlist = allowlist;
    }
    if let Some(channels) = body.channels {
        cfg.channels = channels;
    }
    if let Some(mode) = body.mode {
        cfg.mode = Some(if mode == "public" { "public".into() } else { "owner".into() });
    }
    if let Some(kb) = body.knowledge_base {
        let kb = kb.trim();
        cfg.knowledge_base = if kb.is_empty() { None } else { Some(kb.to_string()) };
    }
    // Multi-agent routing: empty string clears the persona (back to the
    // owner agent); empty list clears the tool restriction.
    if let Some(p) = body.persona {
        let p = p.trim();
        cfg.persona = if p.is_empty() { None } else { Some(p.to_string()) };
    }
    if let Some(tools) = body.persona_tools {
        let tools: Vec<String> =
            tools.into_iter().map(|t| t.trim().to_string()).filter(|t| !t.is_empty()).collect();
        cfg.persona_tools = if tools.is_empty() { None } else { Some(tools) };
    }
    if let Err(e) = connector_catalog::save_connector_config(&cfg) {
        return (StatusCode::INTERNAL_SERVER_ERROR, e).into_response();
    }
    let tx = { state.runtime.cinderpaw_agent_tx.lock().as_ref().cloned() };
    if let Some(tx) = tx {
        let _ = tx.send(json!({ "type": "connectors_reload", "connectors": crate::connectors::resolved_connector_configs() }).to_string()).await;
    }
    Json(connector_catalog::redact_for_frontend(&cfg)).into_response()
}

/// Slice 4b: poke the sidecar to reconcile connectors against the on-disk
/// `~/.feral/connectors.json` — the same `connectors_reload` message the desktop
/// app sends. 503 if the sidecar isn't running.
async fn runtime_connectors_reload(State(state): State<ApiState>) -> impl IntoResponse {
    let tx = { state.runtime.cinderpaw_agent_tx.lock().as_ref().cloned() };
    match tx {
        Some(tx) => {
            if tx.send(json!({ "type": "connectors_reload", "connectors": crate::connectors::resolved_connector_configs() }).to_string()).await.is_err() {
                return (StatusCode::SERVICE_UNAVAILABLE, "sidecar stopped accepting messages")
                    .into_response();
            }
            Json(json!({ "ok": true, "reloaded": true })).into_response()
        }
        None => {
            (StatusCode::SERVICE_UNAVAILABLE, "feral-agent sidecar is not running").into_response()
        }
    }
}

// ── Faza 6 (L6) Meta Evolution ──────────────────────────────────────────────

async fn meta_current(state: State<ApiState>) -> Response {
    meta_roundtrip(state, "meta_status").await
}
/// POST alias for `/meta/evaluate` — same live status+fitness payload.
async fn meta_current_post(state: State<ApiState>) -> Response {
    meta_roundtrip(state, "meta_status").await
}
async fn meta_history(state: State<ApiState>) -> Response {
    meta_roundtrip(state, "meta_history").await
}
async fn meta_evolve(state: State<ApiState>) -> Response {
    meta_roundtrip(state, "meta_evolve").await
}
async fn meta_rollback(state: State<ApiState>) -> Response {
    meta_roundtrip(state, "meta_rollback").await
}

/// Send one meta_* command to the sidecar and return its `meta_result`
/// reply, correlated by the generated `id` on the shared agent-output bus
/// (same subscribe-before-send discipline as `/runtime/chat`).
/// Sprint 1.6 — Memory Resume. Same subscribe-before-send discipline as
/// `meta_roundtrip`; differs only in the inbound `type` ("resume_get") and
/// the matched outbound reply type ("resume_get_result"). The Tauri desktop
/// command `get_last_task` inlines the same pattern (see
/// `src-tauri/src/memory_resume.rs`) so the two call paths can't drift.
async fn runtime_resume(State(state): State<ApiState>) -> Response {
    let tx = { state.runtime.cinderpaw_agent_tx.lock().as_ref().cloned() };
    let Some(tx) = tx else {
        // Sidecar isn't running — first launch with no memory, or gateway
        // running headless without the agent. Empty payload is the right
        // safe default so the TUI / curl callers can render "fresh start".
        return Json(json!({
            "task": null,
            "workspace_id": null,
            "workspace_name": null,
            "last_active_at": null,
        }))
        .into_response();
    };
    let msg_id = uuid::Uuid::new_v4().to_string();
    let mut rx = state.runtime.events_tx.subscribe();
    if tx
        .send(json!({ "type": "resume_get", "id": msg_id }).to_string())
        .await
        .is_err()
    {
        return Json(json!({
            "task": null,
            "workspace_id": null,
            "workspace_name": null,
            "last_active_at": null,
        }))
        .into_response();
    }
    let deadline = std::time::Duration::from_millis(1500);
    loop {
        match tokio::time::timeout(deadline, rx.recv()).await {
            Ok(Ok(ev)) => {
                if ev.event != "cinderpaw://agent-output" {
                    continue;
                }
                let Some(line) = ev.payload.get("data").and_then(|s| s.as_str()) else {
                    continue;
                };
                let Ok(v) = serde_json::from_str::<Value>(line) else { continue };
                if v.get("type").and_then(|t| t.as_str()) == Some("resume_get_result")
                    && v.get("id").and_then(|i| i.as_str()) == Some(msg_id.as_str())
                {
                    return Json(v).into_response();
                }
            }
            Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
            Ok(Err(broadcast::error::RecvError::Closed)) => {
                return Json(json!({
                    "task": null,
                    "workspace_id": null,
                    "workspace_name": null,
                    "last_active_at": null,
                }))
                .into_response();
            }
            Err(_) => {
                return Json(json!({
                    "task": null,
                    "workspace_id": null,
                    "workspace_name": null,
                    "last_active_at": null,
                }))
                .into_response();
            }
        }
    }
}

/// POST /runtime/session/compact — one sidecar round-trip (subscribe-before-
/// send, correlate by id) asking the agent loop to summarize the older
/// portion of a session's transcript now. Mirrors `runtime_resume`'s wire
/// discipline; differs in the inbound type ("compact_session"), the reply
/// ("compact_result"), and a 120s deadline (the summarizer is a real LLM
/// completion, not a lookup).
async fn runtime_session_compact(
    State(state): State<ApiState>,
    body: Option<Json<Value>>,
) -> Response {
    let session_id = body
        .as_ref()
        .and_then(|b| b.get("session_id"))
        .and_then(|s| s.as_str())
        .unwrap_or("default")
        .to_string();
    let tx = { state.runtime.cinderpaw_agent_tx.lock().as_ref().cloned() };
    let Some(tx) = tx else {
        return (StatusCode::SERVICE_UNAVAILABLE, "feral-agent sidecar is not running")
            .into_response();
    };
    let msg_id = uuid::Uuid::new_v4().to_string();
    let mut rx = state.runtime.events_tx.subscribe();
    if tx
        .send(
            json!({ "type": "compact_session", "id": msg_id, "sessionId": session_id })
                .to_string(),
        )
        .await
        .is_err()
    {
        return (StatusCode::SERVICE_UNAVAILABLE, "sidecar stopped accepting messages")
            .into_response();
    }
    let deadline = std::time::Duration::from_secs(120);
    loop {
        match tokio::time::timeout(deadline, rx.recv()).await {
            Ok(Ok(ev)) => {
                if ev.event != "cinderpaw://agent-output" {
                    continue;
                }
                let Some(line) = ev.payload.get("data").and_then(|s| s.as_str()) else { continue };
                let Ok(v) = serde_json::from_str::<Value>(line) else { continue };
                if v.get("type").and_then(|t| t.as_str()) == Some("compact_result")
                    && v.get("id").and_then(|i| i.as_str()) == Some(msg_id.as_str())
                {
                    return Json(v).into_response();
                }
            }
            Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
            Ok(Err(broadcast::error::RecvError::Closed)) | Err(_) => {
                return (StatusCode::GATEWAY_TIMEOUT, "no compact_result from the sidecar")
                    .into_response();
            }
        }
    }
}

async fn meta_roundtrip(State(state): State<ApiState>, op: &'static str) -> Response {
    let tx = { state.runtime.cinderpaw_agent_tx.lock().as_ref().cloned() };
    let Some(tx) = tx else {
        return (StatusCode::SERVICE_UNAVAILABLE, "feral-agent sidecar is not running")
            .into_response();
    };
    let msg_id = uuid::Uuid::new_v4().to_string();
    let mut rx = state.runtime.events_tx.subscribe();
    if tx.send(json!({ "type": op, "id": msg_id }).to_string()).await.is_err() {
        return (StatusCode::SERVICE_UNAVAILABLE, "sidecar stopped accepting messages")
            .into_response();
    }
    let deadline = std::time::Duration::from_secs(10);
    loop {
        match tokio::time::timeout(deadline, rx.recv()).await {
            Ok(Ok(ev)) => {
                if ev.event != "cinderpaw://agent-output" {
                    continue;
                }
                let Some(line) = ev.payload.get("data").and_then(|s| s.as_str()) else { continue };
                let Ok(v) = serde_json::from_str::<Value>(line) else { continue };
                if v.get("type").and_then(|t| t.as_str()) == Some("meta_result")
                    && v.get("id").and_then(|i| i.as_str()) == Some(msg_id.as_str())
                {
                    return Json(v).into_response();
                }
            }
            Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
            Ok(Err(broadcast::error::RecvError::Closed)) => {
                return (StatusCode::SERVICE_UNAVAILABLE, "runtime event bus closed").into_response()
            }
            Err(_) => {
                return (StatusCode::GATEWAY_TIMEOUT, "timed out waiting for meta_result")
                    .into_response()
            }
        }
    }
}

// ── Slice A5 (L5 Governance API — spec §12) ─────────────────────────────
//
// Mirrors `meta_roundtrip` line-by-line: subscribe-before-send, wait on the
// runtime event bus for one `governance_result` correlated by `id`. Differs
// in three ways:
//   1. Filters on `type == "governance_result"` (the new reply union in
//      `CinderpawAgent/src/types.ts`) instead of `"meta_result"`.
//   2. Accepts an optional JSON body whose top-level fields are flattened
//      onto the outbound message alongside `type` + `id`. The sidecar's
//      handler (`CinderpawAgent/src/index.ts`) reads these fields directly —
//      no per-op message shape was added.
//   3. Per spec §12 the routes are tagged read/evolve/govern in comments
//      (no enforcement in v1; a future RBAC layer will branch on the tag).

/// Forward a governance op to the sidecar and return its `governance_result`.
/// Optional `body` fields are flattened onto the outbound message envelope.
async fn governance_roundtrip(
    State(state): State<ApiState>,
    op: &'static str,
    body: Option<Json<Value>>,
) -> Response {
    let tx = { state.runtime.cinderpaw_agent_tx.lock().as_ref().cloned() };
    let Some(tx) = tx else {
        // The supervisor's outbound channel is closed — usually the sidecar
        // crashed at boot or was never spawned. Without this log the operator
        // only sees "503" from the CLI; with it, gateway.log points at the
        // root cause (broken self-src bundle, byok.json corruption, etc.).
        tracing::warn!(
            op = %op,
            "governance_roundtrip: sidecar channel is closed (tx=None); \
             returning 503 — sidecar process likely crashed"
        );
        return (StatusCode::SERVICE_UNAVAILABLE, "feral-agent sidecar is not running")
            .into_response();
    };
    let msg_id = uuid::Uuid::new_v4().to_string();
    let mut rx = state.runtime.events_tx.subscribe();

    // Build the outbound envelope. Body fields overwrite defaults; missing
    // body → minimal `{ type, id }` envelope (the sidecar's handler defaults
    // missing fields to sensible empties — see brief §1 op-mapping table).
    let mut payload = json!({ "type": op, "id": msg_id });
    if let Some(Json(Value::Object(map))) = body {
        for (k, v) in map {
            payload[k] = v;
        }
    }
    if tx.send(payload.to_string()).await.is_err() {
        // The channel accepted our `send` in the check above but rejected
        // this one — the sidecar died between the two reads. Surface it
        // the same way as the closed-channel case so the operator doesn't
        // have to learn two failure shapes.
        tracing::warn!(
            op = %op,
            "governance_roundtrip: tx.send() rejected — sidecar dropped between \
             the lock and the send"
        );
        return (StatusCode::SERVICE_UNAVAILABLE, "sidecar stopped accepting messages")
            .into_response();
    }
    let deadline = std::time::Duration::from_secs(10);
    loop {
        match tokio::time::timeout(deadline, rx.recv()).await {
            Ok(Ok(ev)) => {
                if ev.event != "cinderpaw://agent-output" {
                    continue;
                }
                let Some(line) = ev.payload.get("data").and_then(|s| s.as_str()) else {
                    continue;
                };
                let Ok(v) = serde_json::from_str::<Value>(line) else {
                    continue;
                };
                if v.get("type").and_then(|t| t.as_str()) == Some("governance_result")
                    && v.get("id").and_then(|i| i.as_str()) == Some(msg_id.as_str())
                {
                    return Json(v).into_response();
                }
            }
            Ok(Err(broadcast::error::RecvError::Lagged(_))) => continue,
            Ok(Err(broadcast::error::RecvError::Closed)) => {
                return (StatusCode::SERVICE_UNAVAILABLE, "runtime event bus closed")
                    .into_response();
            }
            Err(_) => {
                return (StatusCode::GATEWAY_TIMEOUT, "timed out waiting for governance_result")
                    .into_response();
            }
        }
    }
}

